const $=s=>document.querySelector(s);
const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
const artifacts=[
{id:'53960',title:'错铜青铜壶',period:'东周 · 公元前5世纪',type:'青铜',material:'青铜、铜镶嵌',tag:'免费赏读',desc:'以铜为笔，在青铜上留下流动的纹样。',intro:'这是一件来自公元前5世纪的盛酒器。错落的铜色纹饰与深沉的青铜器身相映，让日常器用拥有了礼仪的秩序与美感。',body:'壶是古代的盛酒器。东周时期，青铜器的器形逐渐趋于简洁，装饰却愈加细密。这件器物将铜镶入青铜表面，以材质的色差组织纹样。观看时，不妨沿着器身的装饰带移动视线，留意纹样如何适应器形的曲面。',look:'先看器身轮廓，再看铜镶嵌与底色的对比。把目光从整体移到细部，会发现工艺如何让器物产生节奏。',time:'约 3 分钟',source:'https://www.metmuseum.org/art/collection/search/53960'},
{id:'52930',title:'乾隆时期瓷瓶',period:'清 · 乾隆时期（1736—1795）',type:'陶瓷',material:'瓷',tag:'免费赏读',desc:'在器形与釉色之间，寻找一份从容。',intro:'这件中国清代瓷瓶，制作于乾隆时期。以一件器物为入口，我们得以近看瓷器的造型、表面与时代审美。',body:'赏瓷可以从轮廓开始：口沿、颈部、肩部和腹部如何连接，决定了器物的姿态。随后观察表面装饰，留意色彩与留白的关系。最后再把眼光收回整体，感受细部如何服务于完整的造型。',look:'试着遮住标签，用半分钟只看轮廓。再观察光线落在瓷器表面时的变化，建立你自己的观看顺序。',time:'约 3 分钟',source:'https://www.metmuseum.org/art/collection/search/52930'},
{id:'49055',title:'陈洪绶《山水》',period:'明 · 陈洪绶（1598/99—1652）',type:'书画',material:'绘画',tag:'深度解读',desc:'把目光放慢，走进画中的一隅。',intro:'远山、江水与亭阁相互呼应。陈洪绶笔下的山水，让自然与文人的生活空间在画面中相遇。',body:'这幅作品以水面和远山展开空间，亭阁则为山水增添了可游可居的意味。中国园林与山水画常以相近的构图方式组织景致：借助遮挡、疏密与远近，让有限的空间唤起更广阔的想象。',look:'先找出画面中的建筑，再循着水岸走向远山。留意哪些地方有笔墨，哪些地方让纸面自己说话。',time:'约 4 分钟',source:'https://www.metmuseum.org/art/collection/search/49055'},
{id:'58526',title:'北方有盖铜釜',period:'中国北方 · 公元2—4世纪',type:'青铜',material:'青铜',tag:'深度解读',desc:'一件炊器，也是生活留下的形状。',intro:'釜是一种炊煮器具。这类青铜炊器与草原游牧人群的生活有关，让我们从礼仪之外，看见器物更贴近日常的一面。',body:'除了用于礼仪与宴饮的容器，炊煮器也是理解古代生活的入口。观察这件有盖铜釜时，可以从实用的角度提问：盖子怎样与器身配合？器物的轮廓，如何适应它的用途？这些问题帮助我们把眼前的物，重新放回人的生活。',look:'将它与盛酒用的壶比较。想一想，功能如何影响口部、腹部和盖子的设计。',time:'约 3 分钟',source:'https://www.metmuseum.org/art/collection/search/58526'}
];
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let saved=readStore('guanwu-saved',[]),member=readStore('guanwu-demo-member',false),city='全部目的地',filter='全部',query='',activeRoute=readStore('guanwu-route',false);
const app=$('#app');let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('浏览器未允许保存，当前操作仅在本次浏览有效')}}
function save(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist('guanwu-saved',saved);document.querySelectorAll(`[data-save="${id}"]`).forEach(b=>{b.classList.toggle('saved',saved.includes(id));b.setAttribute('aria-pressed',String(saved.includes(id)));b.setAttribute('aria-label',saved.includes(id)?'取消收藏':'收藏这件文物')});toast(saved.includes(id)?'已收藏，留待下次慢慢看':'已取消收藏');if(location.hash==='#saved')render(false)}
function card(a){return `<article class="artifact"><button class="art-image" data-detail="${a.id}" aria-label="查看${a.title}"><img src="../assets/${a.id}.jpg" alt="${a.title}，大都会艺术博物馆开放馆藏" loading="lazy"><span class="badge">${a.tag}</span></button><button class="save-btn ${saved.includes(a.id)?'saved':''}" data-save="${a.id}" aria-label="${saved.includes(a.id)?'取消收藏':'收藏这件文物'}" aria-pressed="${saved.includes(a.id)}">${icon('heart')}</button><h3><button data-detail="${a.id}">${a.title}</button></h3><div class="meta">${a.period}</div><div class="card-foot"><span>大都会艺术博物馆</span><span>${a.time} ↗</span></div></article>`}
function title(kicker,name,sub){return `<div class="intro"><div><div class="eyebrow">${kicker}</div><h1>${name}</h1><p>${sub}</p></div><div class="date-note">慢慢看，才看得见。</div></div>`}
function sectionTitle(name,en,link,label){return `<div class="section-head"><div class="section-title"><h2>${name}</h2><span>${en}</span></div>${link?`<a class="text-link" href="${link}">${label} ${icon('arrow')}</a>`:''}</div>`}
function journeyCard(){return `<button class="journey-photo" data-action="route"><img src="../assets/great-wall.jpg" alt="长城沿山脊蜿蜒延伸" loading="lazy"><div><small>BEIJING · 北京</small><h3>循着山脊，读一段长城</h3><p>山河漫游 · 3 个观察停靠点 ${activeRoute?'· 已加入行程':'↗'}</p></div></button>`}
function home(){return `${title('A LITTLE CURIOSITY, A BIGGER WORLD','让好奇心，带你远行','走进一座博物馆，读懂一方水土。每一次相遇，都值得细看。')}<section class="hero" aria-label="本期精选：长城"><img src="../assets/great-wall.jpg" alt="苍翠群山中的长城" fetchpriority="high"><div class="hero-content"><div class="hero-kicker">本期精选 · 山河之间</div><h2>山河入眼，<br>文物入心。</h2><p>越过时光的山脊，与千年的故事不期而遇。<br>从一处风景开始，重新认识脚下的土地。</p><button class="hero-cta" data-action="route">开启这段旅程 ${icon('arrow')}</button></div><div class="hero-bottom"><span>中国 · 长城 / THE GREAT WALL</span><div class="hero-line"></div><span class="hero-count"><b>01</b> / 01</span></div></section><div class="categories"><button class="category" data-go="collection">${icon('museum')}<span>博物馆藏<small>时间里的珍藏</small></span><b>↗</b></button><button class="category" data-go="journeys">${icon('route')}<span>山河漫游<small>土地上的故事</small></span><b>↗</b></button><button class="category" data-action="daily">${icon('discover')}<span>每日一物<small>与一件好物相遇</small></span><b>↗</b></button><button class="category" data-action="membership">${icon('heart')}<span>深度赏读<small>把美看得更深</small></span><b>↗</b></button></div><section>${sectionTitle('值得驻足','CURATED COLLECTIONS','#collection','探索全部馆藏')}<div class="tabs" role="tablist" aria-label="馆藏分类">${['全部','青铜','陶瓷','书画'].map(t=>`<button class="tab ${filter===t?'active':''}" data-filter="${t}" role="tab" aria-selected="${filter===t}">${t==='全部'?'精选推荐':t+'之美'}</button>`).join('')}</div><div class="cards" id="home-cards">${artifacts.filter(a=>filter==='全部'||a.type===filter).map(card).join('')}</div></section><section class="section">${sectionTitle('把风景读成故事','BEYOND THE MUSEUM','#journeys','去山河间走走')}<div class="journey-grid">${journeyCard()}<div class="editorial"><div class="eyebrow">THE ART OF LOOKING</div><h3>不必急着看完，<br>试着真正看见。</h3><p>从一条纹样、一抹釉色开始，<br>让观看成为你与历史之间的对话。</p><button data-action="looking">写给第一次走进博物馆的你 ↗</button></div></div></section>`}
function collection(){return `${title('THE COLLECTIONS','在器物里，与时间相逢','精选中国艺术馆藏 · 当前收录大都会艺术博物馆开放资源')}<form class="search-box" id="search-form"><input type="search" id="collection-search" placeholder="搜索文物、朝代、材质…" aria-label="搜索文物" value="${escapeHTML(query)}"><button class="solid-btn" type="submit">搜索</button></form><div class="filter-row">${['全部','青铜','陶瓷','书画'].map(t=>`<button class="pill ${filter===t?'active':''}" data-filter="${t}">${t}</button>`).join('')}</div><div id="collection-results">${collectionResults()}</div>`}
function matches(){return artifacts.filter(a=>(filter==='全部'||a.type===filter)&&`${a.title}${a.period}${a.material}${a.type}大都会艺术博物馆`.includes(query.trim()))}
function collectionResults(){const list=matches();return list.length?`<div class="section-head"><span class="eyebrow">${list.length} 件馆藏 · 慢慢欣赏</span></div><div class="cards">${list.map(card).join('')}</div>`:`<div class="empty"><h2>暂时没有找到这件藏品</h2><p>试试“青铜”“明”或“瓷”，也可以浏览全部馆藏。</p><button class="solid-btn" data-action="reset-search">浏览全部馆藏</button></div>`}
function detail(id){const a=artifacts.find(a=>a.id===id);if(!a)return `<div class="empty"><h2>暂未找到这件馆藏</h2><a href="#collection">返回馆藏 →</a></div>`;const locked=a.tag==='深度解读'&&!member;return `<button class="back" data-go="collection">← 返回博物馆藏</button><div class="detail-grid"><div><img class="detail-image" src="../assets/${a.id}.jpg" alt="${a.title}"><p class="meta" style="color:#8c957f;font-size:10px;line-height:2">图片：The Metropolitan Museum of Art · 公共领域<br>藏品所在地：美国纽约，非中国境内馆藏</p></div><div class="detail-copy"><div class="eyebrow">A CLOSER LOOK · ${a.type}</div><h1>${a.title}</h1><p class="lead">${a.intro}</p><div class="facts"><div><small>年代</small><span>${a.period}</span></div><div><small>材质</small><span>${a.material}</span></div><div><small>收藏机构</small><span>大都会艺术博物馆</span></div><div><small>阅读时长</small><span>${a.time}</span></div></div><div class="detail-actions"><button class="solid-btn" data-action="narrate" data-id="${id}">▷ 朗读简介</button><button class="outline-btn ${saved.includes(id)?'saved':''}" data-save="${id}" aria-pressed="${saved.includes(id)}">${saved.includes(id)?'已收藏':'收藏这件文物'}</button></div><div class="article-body"><h2>看见器物背后的故事</h2><p>${a.body}</p>${locked?`<div class="locked"><h3>再靠近一点，看见更多</h3><p>简介可免费阅读。解锁深度赏读，继续探索观察方法与细节。</p><button class="solid-btn" data-action="membership">体验完整赏读 →</button></div>`:`<h2>不妨这样看</h2><p>${a.look}</p>`}<h2>资料与延伸</h2><p><a href="${a.source}" target="_blank" rel="noopener">前往馆方查看藏品原始资料 ↗</a></p><p style="font:10px/1.9 Arial;color:#929c87">基础信息依据馆方资料；观察提示为观物编辑撰写。展陈状态、开放时间与参观要求，请以馆方信息为准。</p></div></div></div>`}
function journeys(){return `${title('JOURNEYS & LANDSCAPES','走进山河，也走进故事','用一条漫游线路，连接风景、建筑与人文。')}<div class="filter-row"><button class="pill ${city==='全部目的地'?'active':''}" data-city="全部目的地">全部目的地</button><button class="pill ${city==='北京'?'active':''}" data-city="北京">北京</button><button class="pill ${city==='纽约'?'active':''}" data-city="纽约">纽约</button></div>${city==='纽约'?`<div class="empty"><h2>先从一件馆藏开始</h2><p>纽约的城市漫游正在筹备，先看看大都会里的中国艺术。</p><button class="solid-btn" data-go="collection">探索中国艺术馆藏 →</button></div>`:`<div class="journey-grid">${journeyCard()}<div class="editorial"><div class="eyebrow">YOUR OWN PACE</div><h3>留一点时间，<br>给路上的发现。</h3><p>线路是观看提示，不含门票与预约。<br>按自己的节奏，选择一个地方慢慢看。</p><button data-action="route">查看长城漫游手记 →</button></div></div>`}`}
function route(){return `${title('BEIJING · FIELD NOTES','循着山脊，读一段长城','中国 · 北京 | 文化景观漫游 | 3 个观察停靠点')}<img class="route-hero" src="../assets/great-wall.jpg" alt="长城与远山"><div class="route-layout"><section><div class="route-stop"><small>01 / 出发前</small><h3>从整体，看见山势</h3><p>长城在1987年被列入《世界遗产名录》。它并非孤立的一道墙，而是跨越地域与时代的防御系统。登临前，先观察城墙如何依山而行，想一想山地怎样成为防御的一部分。</p></div><div class="route-stop"><small>02 / 驻足时</small><h3>从细部，读懂建造</h3><p>留意脚下的砖石、墙体的起伏与敌台的位置。把镜头稍稍放下，用眼睛比较不同位置的结构。请勿攀爬未开放段，也不要触碰或带走遗存。</p></div><div class="route-stop"><small>03 / 回望处</small><h3>让风景，留在记忆里</h3><p>在安全的开放区域选择一处视野开阔的地方，回望走过的方向。拍一张远景，再记下一处吸引你的细节，让这次漫游留下属于自己的观察。</p></div><a class="text-link" href="https://whc.unesco.org/en/list/438/" target="_blank" rel="noopener">资料来源：联合国教科文组织 · 长城 ↗</a></section><aside class="route-panel"><div class="eyebrow">BEFORE YOU GO</div><h3>把旅途交给从容</h3><p>这是一份观察手记，不是实时导航。图片为长城主题图，不指向特定入口。</p><p>出发前请选择官方开放景区，核实开放时间、天气与预约要求。穿着防滑鞋，带好饮水，预留休息时间。</p><button class="solid-btn" data-action="add-route">${activeRoute?'✓ 已加入我的行程':'＋ 加入我的行程'}</button><p style="font-size:10px">行程保存在当前浏览器，可在“我的收藏”查看。</p></aside></div>`}
function savedPage(){return `${title('YOUR LITTLE MUSEUM','收藏每一次心动','喜欢的器物、想去的远方，都在这里等你。')}${saved.length?`<div class="cards">${artifacts.filter(a=>saved.includes(a.id)).map(card).join('')}</div>`:`<div class="empty">${icon('heart')}<h2>你的私人小馆，等待第一件收藏</h2><p>点击馆藏图片上的心形，把喜欢的文物留在这里。</p><button class="solid-btn" data-go="collection">去发现一件好物 →</button></div>`}${activeRoute?`<section class="section">${sectionTitle('我的行程','MY JOURNEYS')}<div class="journey-grid">${journeyCard()}</div><button class="text-link" style="margin-top:15px" data-action="remove-route">移除这段行程</button></section>`:''}`}
function escapeHTML(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(scroll=true){const hash=location.hash.slice(1)||'discover';const section=hash.startsWith('detail/')?'collection':hash==='route'?'journeys':hash;document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===section));$('#page-label').textContent=({discover:'发现灵感',collection:'博物馆藏',journeys:'山河漫游',saved:'我的收藏'})[section]||'发现灵感';if(window.speechSynthesis)window.speechSynthesis.cancel();app.innerHTML=hash.startsWith('detail/')?detail(hash.split('/')[1]):hash==='collection'?collection():hash==='journeys'?journeys():hash==='saved'?savedPage():hash==='route'?route():home();if(scroll)window.scrollTo({top:0,behavior:'instant'});document.title=($('#app h1')?.textContent||'观物')+' · 观物 GUANWU';}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
function membership(){modal(`<div class="eyebrow">GUANWU · MEMBERSHIP</div><h2 id="modal-title">让好奇，走得更远</h2><p>从一件器物，到一个时代。知行会员为愿意慢慢看的人，准备更深入的阅读。</p><ul><li>完整阅读当前全部馆藏的观察提示</li><li>收藏喜爱的文物，建立自己的小馆</li><li>收下沿途的人文漫游手记</li></ul><div class="price">免费体验 <small>首版预览</small></div><p class="demo-note">付费功能尚未开放。本次解锁仅演示会员流程，不会扣款；体验状态仅保存在当前浏览器。</p><button class="solid-btn" data-action="unlock">${member?'已解锁 · 继续探索':'免费体验完整赏读 →'}</button>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.detail){location.hash='detail/'+b.dataset.detail;return}if(b.dataset.save){save(b.dataset.save);return}if(b.dataset.go){location.hash=b.dataset.go;return}if(b.dataset.filter){filter=b.dataset.filter;render(false);return}if(b.dataset.city){setCity(b.dataset.city);render(false);return}const a=b.dataset.action;if(a==='membership')membership();if(a==='route')location.hash='route';if(a==='daily')location.hash='detail/'+artifacts[new Date().getDate()%artifacts.length].id;if(a==='location')modal(`<div class="eyebrow">DESTINATIONS</div><h2 id="modal-title">下一站，去哪里？</h2><p>选择目的地，查看对应的漫游与馆藏内容。</p><div class="city-list">${['全部目的地','北京','纽约'].map(c=>`<button data-action="select-city" data-value="${c}">${c}<span>→</span></button>`).join('')}</div>`);if(a==='select-city'){setCity(b.dataset.value);$('#modal').close();location.hash=city==='纽约'?'collection':'journeys';render()}if(a==='search'){query='';filter='全部';location.hash='collection';render();$('#collection-search')?.focus()}if(a==='profile')modal(`<div class="eyebrow">YOUR GUANWU</div><h2 id="modal-title">你好，观物旅人</h2><p>你已收藏 ${saved.length} 件文物，记录 ${activeRoute?1:0} 段行程。</p><p>当前为访客体验，收藏保存在这台设备的浏览器中。</p><button class="solid-btn" data-action="open-saved">打开我的收藏 →</button>`);if(a==='open-saved'){$('#modal').close();location.hash='saved'}if(a==='unlock'){member=true;persist('guanwu-demo-member',true);$('#modal').close();render(false);toast('完整赏读已解锁 · 免费演示，未产生扣款')}if(a==='reset-search'){query='';filter='全部';render(false)}if(a==='add-route'){activeRoute=true;persist('guanwu-route',true);render(false);toast('已加入行程，可在“我的收藏”查看')}if(a==='remove-route'){activeRoute=false;persist('guanwu-route',false);render(false);toast('已移除行程')}if(a==='about')modal(`<div class="eyebrow">ABOUT GUANWU</div><h2 id="modal-title">以好奇，连接世界</h2><p>观物是一个博物与人文导览体验。首版收录4件公开馆藏与1份长城主题漫游手记，内容会逐步扩充。</p><p>馆藏图片来自 The Metropolitan Museum of Art Open Access，下载时经 API 核实为公共领域。长城摄影来自 Unsplash，照片仅用于主题展示。各件藏品详情均附馆方链接。</p><div class="source-links"><a href="../assets/sources.json" target="_blank" rel="noopener">查看图片及藏品来源记录 ↗</a><a href="https://www.metmuseum.org/about-the-met/policies-and-documents/open-access" target="_blank" rel="noopener">The Met 开放获取政策 ↗</a><a href="https://images.unsplash.com/photo-1508804185872-d7badad00f7d" target="_blank" rel="noopener">长城摄影 · Unsplash ↗</a><a href="https://whc.unesco.org/en/list/438/" target="_blank" rel="noopener">长城世界遗产资料 ↗</a></div><p class="demo-note">当前为可交互的移动网页体验，非已上线微信小程序；会员、收藏与行程为本地体验，不含真实支付或账号同步。</p>`);if(a==='looking')modal(`<div class="eyebrow">THE ART OF LOOKING</div><h2 id="modal-title">给第一次看展的你</h2><p>不必记住每个年代，也不必走遍每个展厅。先选择一件令你停下来的器物。</p><ul><li>先看形状。它的轮廓让你联想到什么？</li><li>再看材料。光线怎样落在它的表面？</li><li>靠近细节。有没有重复的纹样或手工痕迹？</li><li>最后读标签。试着用信息回答自己的问题。</li></ul><p>离开时，带走一个新问题，就已经是一场很好的参观。</p>`);if(a==='narrate'){if(!('speechSynthesis'in window)){toast('此浏览器暂不支持朗读，请阅读下方文字');return}if(speechSynthesis.speaking){speechSynthesis.cancel();b.textContent='▷ 朗读简介';return}const art=artifacts.find(x=>x.id===b.dataset.id);const utter=new SpeechSynthesisUtterance(art.title+'。'+art.intro);utter.lang='zh-CN';utter.rate=.85;utter.onend=()=>b.textContent='▷ 朗读简介';utter.onerror=()=>{b.textContent='▷ 朗读简介';toast('朗读服务暂不可用，可继续阅读文字')};b.textContent='Ⅱ 停止朗读';speechSynthesis.speak(utter)}});
function setCity(c){city=c;$('#city-label').textContent=c}
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();query=$('#collection-search').value;$('#collection-results').innerHTML=collectionResults()}});
document.addEventListener('input',e=>{if(e.target.id==='collection-search'){query=e.target.value;$('#collection-results').innerHTML=collectionResults()}});
$('.close-dialog').addEventListener('click',()=>$('#modal').close());$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});window.addEventListener('hashchange',()=>render());render();
